#!/usr/bin/env sh
# Registers this stack's S3 deployment-package store with the Policy Editor.
#
# The PAP `setup` tool generates config/options.yml from the image template,
# overwriting anything a server profile ships at the same path, so the store
# is added here instead: post-setup, pre-server-start (hook 50 slot), by
# inserting the deploymentPackageStores entry into the generated file. The
# Publish action in the Deployment Manager UI (and the equivalent
# POST /api/deployment-package-store/<name>/package call made by
# scripts/build-package.sh) then writes the package AND the pointer file
# that the PAZ-side S3 store poller expects.
#
# The PAZ-side store (server-profiles/pingauthorize/pd.profile/dsconfig/
# 30-embedded-pdp.dsconfig.subst) must point at the same bucket+prefix and
# use the same security level (unsigned) for the package to be accepted.
#
# Env (wired from the paz-s3 Secret by helm/paz/values.yaml):
#   PAZ_S3_BUCKET / PAZ_S3_PREFIX / PAZ_S3_REGION /
#   PAZ_S3_ACCESS_KEY / PAZ_S3_SECRET_KEY

test "${VERBOSE}" = "true" && set -x

# shellcheck source=../../../../pingcommon/opt/staging/hooks/pingcommon.lib.sh
. "${HOOKS_DIR}/pingcommon.lib.sh"

OPTIONS_FILE="${SERVER_ROOT_DIR}/config/options.yml"

for var in PAZ_S3_BUCKET PAZ_S3_PREFIX PAZ_S3_REGION PAZ_S3_ACCESS_KEY PAZ_S3_SECRET_KEY; do
    if test -z "$(eval "echo \${${var}:-}")"; then
        echo "50-package-store: ${var} not set - skipping package store registration"
        return 0
    fi
done

if grep -q "name: paz-perf-packages" "${OPTIONS_FILE}" 2>/dev/null; then
    echo "50-package-store: store already registered"
    return 0
fi

# Insert the store as the first entry under deploymentPackageStores:.
# Options.yml is generated by setup, so the key is always present.
sed -i "/^deploymentPackageStores:$/a\\
  - name: paz-perf-packages\\
    description: PAZ sideband performance stack package store\\
    type: s3bucket\\
    securityLevel: unsigned\\
    config:\\
      bucket: ${PAZ_S3_BUCKET}\\
      prefix: ${PAZ_S3_PREFIX}\\
      region: ${PAZ_S3_REGION}\\
      accessKey: ${PAZ_S3_ACCESS_KEY}\\
      secretKey: ${PAZ_S3_SECRET_KEY}" "${OPTIONS_FILE}"

echo "50-package-store: registered S3 store paz-perf-packages (bucket ${PAZ_S3_BUCKET}, prefix ${PAZ_S3_PREFIX})"
